const raw = $input.item.json;
let tips = [];

if (Array.isArray(raw.tips)) {
  tips = raw.tips;
} else if (raw.text) {
  const text = String(raw.text).trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
  try {
    const parsed = JSON.parse(text);
    tips = Array.isArray(parsed.tips) ? parsed.tips : [];
  } catch (error) {
    tips = text.split(/\n+/).map(line => line.replace(/^[-\d.、\s]+/, '').trim());
  }
}

tips = tips
  .map(tip => String(tip || '').trim())
  .filter(Boolean)
  .slice(0, 6);

if (tips.length === 0) {
  const language = $('参数组装').first().json.language || 'zh';
  const fallbackTipsZh = [
    '希望故事情境更有悬念，让学生从一封任务信或线索卡进入挑战。',
    '希望Execute阶段加入小组合作竞赛，让最终产出更有挑战性。',
    '希望语言工具箱更聚焦口语输出，增加可反复套用的课堂句型。',
    '希望成长目标更突出团队协作、情绪表达和解决问题后的成就感。'
  ];
  const fallbackTipsEn = [
    'Make the story context more suspenseful, with students entering through a mission letter or clue card.',
    'Add a team-based challenge in the Execute phase to make the final output more meaningful.',
    'Make the language toolkit focus more on oral output and reusable classroom sentence patterns.',
    'Strengthen growth goals around teamwork, emotional expression, and a sense of accomplishment.'
  ];
  tips = language === 'en' ? fallbackTipsEn : fallbackTipsZh;
}

return { tips };

const input = $input.item.json.body;
const language = input.language || 'zh';
const outputLanguage = input.outputLanguage || (language === 'en' ? 'English' : 'Chinese');

const phaseInfo = {
  engage: { label: 'Engage', description: '建立情感连接与情境导入，激发好奇心和参与动机', idPrefix: 'e', timeRatio: '15%' },
  empower: { label: 'Empower', description: '输入语言知识与SEL技能，进行体感探索', idPrefix: 'em', timeRatio: '40%' },
  execute: { label: 'Execute', description: '通过艺术表达完成终极产出任务，体验合作分享', idPrefix: 'ex', timeRatio: '30%' },
  elevate: { label: 'Elevate', description: '反思、内化并建立积极情绪闭环', idPrefix: 'el', timeRatio: '15%' }
};

const phaseKey = input.phaseKey || 'engage';
const info = phaseInfo[phaseKey];

const phaseInfoEn = {
  engage: { label: 'Engage', description: 'Build emotional connection, introduce the context, and spark curiosity and motivation' },
  empower: { label: 'Empower', description: 'Introduce language knowledge and SEL skills through embodied exploration' },
  execute: { label: 'Execute', description: 'Complete the final output task through creative expression and collaborative sharing' },
  elevate: { label: 'Elevate', description: 'Reflect, internalize learning, and close the positive emotion loop' }
};
if (language === 'en' && phaseInfoEn[phaseKey]) {
  info.label = phaseInfoEn[phaseKey].label;
  info.description = phaseInfoEn[phaseKey].description;
}
const existingStepCount = input.existingStepCount || 0;
const insertIndex = input.insertIndex != null ? input.insertIndex : existingStepCount;
const nextIndex = existingStepCount + 1;
const stepId = `${info.idPrefix}${nextIndex}`;

const parseDurationMinutes = (value) => {
  const numbers = String(value || '').match(/\d+(?:\.\d+)?/g);
  if (!numbers || numbers.length === 0) return 0;
  return Number(numbers[numbers.length - 1]) || 0;
};
const formatMinutes = (value) => Number.isInteger(value) ? String(value) : value.toFixed(1).replace(/\.0$/, '');
const ratioValue = Number(String(info.timeRatio || '').replace('%', '')) / 100;
const phaseRecommendedMinutes = parseDurationMinutes(input.duration || '60分钟') * (Number.isFinite(ratioValue) ? ratioValue : 0);
const currentStepMinutes = Array.isArray(input.currentSteps)
  ? input.currentSteps.reduce((sum, step) => sum + parseDurationMinutes(step.time || step.duration), 0)
  : 0;
const phaseRemainingMinutes = Math.max(0, phaseRecommendedMinutes - currentStepMinutes);

let existingStepsStr = '暂无已有环节';
if (input.currentSteps && input.currentSteps.length > 0) {
  existingStepsStr = input.currentSteps.map((s, i) => `${i+1}. ${s.title} (${s.time || s.duration || '未设置时长'})`).join('\n');
}

let insertContextStr = '';
if (insertIndex >= existingStepCount) {
  insertContextStr = '新环节应接续在所有已有环节之后，作为该阶段的最后一个环节。';
} else {
  const prev = input.prevStep;
  const next = input.nextStep;
  let parts = [`新环节将插入到第 ${insertIndex + 1} 个位置。`];
  if (prev) {
    parts.push(`前置环节：${prev.title}（${prev.time || prev.duration || '未设置时长'}）—— 目标：${prev.objective || '无'}`);
  } else {
    parts.push('这是该阶段的第一个环节。');
  }
  if (next) {
    parts.push(`后续环节：${next.title}（${next.time || next.duration || '未设置时长'}）—— 目标：${next.objective || '无'}`);
    parts.push('新环节必须在叙事和教学逻辑上衔接前后环节，起到承上启下的过渡作用。');
  }
  insertContextStr = parts.join('\n');
}

let otherPhasesStr = '无';
if (input.otherPhases) {
  try {
    otherPhasesStr = typeof input.otherPhases === 'string' ? input.otherPhases : JSON.stringify(input.otherPhases, null, 2);
  } catch (e) {
    otherPhasesStr = '无法解析';
  }
}

return {
  language,
  outputLanguage,
  age: input.age || '7-9岁',
  duration: input.duration || '60分钟',
  scale: input.scale || '≤ 8人',
  title: input.title || '未命名课件',
  vocabulary: (input.vocabulary && input.vocabulary.length > 0) ? (Array.isArray(input.vocabulary) ? input.vocabulary.join(', ') : input.vocabulary) : '请根据主题推荐词汇',
  grammar: (input.grammar && input.grammar.length > 0) ? (Array.isArray(input.grammar) ? input.grammar.join(', ') : input.grammar) : '请根据主题推荐句型',
  theme: input.theme || '默认主题',
  requirements: input.requirements || '',
  phaseKey,
  phaseLabel: info.label,
  phaseDescription: info.description,
  timeRatio: info.timeRatio,
  phaseRecommendedMinutes: formatMinutes(phaseRecommendedMinutes),
  currentStepMinutes: formatMinutes(currentStepMinutes),
  phaseRemainingMinutes: formatMinutes(phaseRemainingMinutes),
  stepId,
  nextIndex,
  existingSteps: existingStepsStr,
  insertContext: insertContextStr,
  otherPhases: otherPhasesStr
};

const input = $input.item.json.body;
const language = input.language || 'zh';
const outputLanguage = input.outputLanguage || (language === 'en' ? 'English' : 'Chinese');

const phaseInfo = {
  engage: { label: 'Engage', description: '建立情感连接与情境导入，激发好奇心和参与动机', timeRatio: '15%' },
  empower: { label: 'Empower', description: '输入语言知识与SEL技能，进行体感探索', timeRatio: '40%' },
  execute: { label: 'Execute', description: '通过艺术表达完成终极产出任务，体验合作分享', timeRatio: '30%' },
  elevate: { label: 'Elevate', description: '反思、内化并建立积极情绪闭环', timeRatio: '15%' }
};

const phaseKey = input.phaseKey || 'engage';
const info = phaseInfo[phaseKey];

const phaseInfoEn = {
  engage: { label: 'Engage', description: 'Build emotional connection, introduce the context, and spark curiosity and motivation' },
  empower: { label: 'Empower', description: 'Introduce language knowledge and SEL skills through embodied exploration' },
  execute: { label: 'Execute', description: 'Complete the final output task through creative expression and collaborative sharing' },
  elevate: { label: 'Elevate', description: 'Reflect, internalize learning, and close the positive emotion loop' }
};
if (language === 'en' && phaseInfoEn[phaseKey]) {
  info.label = phaseInfoEn[phaseKey].label;
  info.description = phaseInfoEn[phaseKey].description;
}

const parseDurationMinutes = (value) => {
  const numbers = String(value || '').match(/\d+(?:\.\d+)?/g);
  if (!numbers || numbers.length === 0) return 0;
  return Number(numbers[numbers.length - 1]) || 0;
};
const formatMinutes = (value) => Number.isInteger(value) ? String(value) : value.toFixed(1).replace(/\.0$/, '');
const ratioValue = Number(String(info.timeRatio || '').replace('%', '')) / 100;
const phaseRecommendedMinutes = parseDurationMinutes(input.duration || '60分钟') * (Number.isFinite(ratioValue) ? ratioValue : 0);
const siblingStepMinutes = Array.isArray(input.siblingSteps)
  ? input.siblingSteps.reduce((sum, step) => sum + parseDurationMinutes(step.time || step.duration), 0)
  : 0;
const replacementMaxMinutes = Math.max(0, phaseRecommendedMinutes - siblingStepMinutes);

let currentStepStr = '无';
if (input.currentStep) {
  const s = input.currentStep;
  currentStepStr = `ID: ${s.id}\n标题: ${s.title}\n时长: ${s.time || s.duration || '未设置时长'}\n目标: ${s.objective || ''}`;
}

let siblingStepsStr = '无';
if (input.siblingSteps && input.siblingSteps.length > 0) {
  siblingStepsStr = input.siblingSteps.map((s, i) => `${i+1}. ${s.title} (${s.time || s.duration || '未设置时长'})`).join('\n');
}

let otherPhasesStr = '无';
if (input.otherPhases) {
  try {
    otherPhasesStr = typeof input.otherPhases === 'string' ? input.otherPhases : JSON.stringify(input.otherPhases, null, 2);
  } catch (e) {
    otherPhasesStr = '无法解析';
  }
}

return {
  language,
  outputLanguage,
  age: input.age || '7-9岁',
  duration: input.duration || '60分钟',
  scale: input.scale || '≤ 8人',
  title: input.title || '未命名课件',
  vocabulary: (input.vocabulary && input.vocabulary.length > 0) 
    ? (Array.isArray(input.vocabulary) ? input.vocabulary.join(', ') : input.vocabulary)
    : '请根据主题推荐词汇',
  grammar: (input.grammar && input.grammar.length > 0) 
    ? (Array.isArray(input.grammar) ? input.grammar.join(', ') : input.grammar)
    : '请根据主题推荐句型',
  theme: input.theme || '默认主题',
  requirements: input.requirements || input.userIdea || '',
  classicName: input.classicName || '',
  phaseKey: phaseKey,
  phaseLabel: info.label,
  phaseDescription: info.description,
  timeRatio: info.timeRatio,
  phaseRecommendedMinutes: formatMinutes(phaseRecommendedMinutes),
  siblingStepMinutes: formatMinutes(siblingStepMinutes),
  replacementMaxMinutes: formatMinutes(replacementMaxMinutes),
  stepId: input.stepId || '',
  currentStep: currentStepStr,
  siblingSteps: siblingStepsStr,
  otherPhases: otherPhasesStr
};

// 解析 LLM 输出的 JSON 文本
let raw = $input.item.json;

// 如果 LLM 输出有 text 字段，从中提取 JSON
if (raw.text && typeof raw.text === 'string') {
  const match = raw.text.match(/\{[\s\S]*\}/);
  if (match) {
    try { raw = JSON.parse(match[0]); } catch (e) {}
  }
}

const step = (raw.step && typeof raw.step === 'object') ? raw.step : raw;

// 补充 activitySteps：按内容动态拆分，避免固定四步模板
if (!step.activitySteps || step.activitySteps.trim() === '') {
  const activity = step.activity || '';
  const sentences = activity.split(/[。！？；;]+/).map(s => s.trim()).filter(Boolean);
  const makeStepName = (text, index) => {
    const cleaned = String(text || '').replace(/[“”\"'，、。！？；;：:（）()]/g, ' ').trim();
    const firstWords = cleaned.split(/\s+/).filter(Boolean).slice(0, 2).join('');
    if (firstWords) return firstWords.slice(0, 8);
    return `课堂推进${index + 1}`;
  };
  const targetCount = Math.max(2, Math.min(6, sentences.length || 3));
  const size = Math.max(1, Math.ceil((sentences.length || 1) / targetCount));
  const parts = [];
  for (let i = 0; i < targetCount; i++) {
    const chunk = sentences.slice(i * size, (i + 1) * size);
    const text = chunk.length > 0 ? chunk.join('。') + '。' : '教师根据课堂进展自然推进活动。';
    parts.push(makeStepName(text, i) + '：' + text);
  }
  step.activitySteps = parts.join('\n');
}

// 补充 resources（从 assets[].title 提取）
if (!step.resources || step.resources.trim() === '') {
  const assets = Array.isArray(step.assets) ? step.assets : [];
  step.resources = assets.map(a => a.title || '').filter(Boolean).join('、');
}

// 补充 scenario（从 activity 第一句截取）
if (!step.scenario || step.scenario.trim() === '') {
  const activity = step.activity || '';
  const first = activity.split(/[。！？]/)[0] || '';
  step.scenario = first.length > 60 ? first.slice(0, 60).replace(/[，、]$/, '') : first;
}

return { step: step };

const input = $input.item.json.body;
const language = input.language || 'zh';
const outputLanguage = input.outputLanguage || (language === 'en' ? 'English' : 'Chinese');

const phaseInfo = {
  engage: {
    label: 'Engage',
    description: '建立情感连接与情境导入，激发好奇心和参与动机',
    timeRatio: '15%'
  },
  empower: {
    label: 'Empower',
    description: '输入语言知识与SEL技能，进行体感探索',
    timeRatio: '40%'
  },
  execute: {
    label: 'Execute',
    description: '通过艺术表达完成终极产出任务，体验合作分享',
    timeRatio: '30%'
  },
  elevate: {
    label: 'Elevate',
    description: '反思、内化并建立积极情绪闭环',
    timeRatio: '15%'
  }
};

const phaseKey = input.phaseKey || 'engage';
const info = phaseInfo[phaseKey];

const phaseInfoEn = {
  engage: { label: 'Engage', description: 'Build emotional connection, introduce the context, and spark curiosity and motivation' },
  empower: { label: 'Empower', description: 'Introduce language knowledge and SEL skills through embodied exploration' },
  execute: { label: 'Execute', description: 'Complete the final output task through creative expression and collaborative sharing' },
  elevate: { label: 'Elevate', description: 'Reflect, internalize learning, and close the positive emotion loop' }
};
if (language === 'en' && phaseInfoEn[phaseKey]) {
  info.label = phaseInfoEn[phaseKey].label;
  info.description = phaseInfoEn[phaseKey].description;
}

const parseDurationMinutes = (value) => {
  const match = String(value || '').match(/\d+(?:\.\d+)?/);
  return match ? Number(match[0]) : 60;
};
const formatMinutes = (value) => Number.isInteger(value) ? String(value) : value.toFixed(1).replace(/\.0$/, '');
const ratioValue = Number(String(info.timeRatio || '').replace('%', '')) / 100;
const phaseRecommendedMinutes = parseDurationMinutes(input.duration || '60分钟') * (Number.isFinite(ratioValue) ? ratioValue : 0);

let otherPhasesStr = '无';
if (input.currentCourseData) {
  try {
    const courseData = typeof input.currentCourseData === 'string' 
      ? JSON.parse(input.currentCourseData) 
      : input.currentCourseData;
    const otherPhases = {};
    for (const [key, value] of Object.entries(courseData)) {
      if (key !== phaseKey && key !== 'courseOverview') {
        otherPhases[key] = { title: value.title, steps: value.steps };
      }
    }
    otherPhasesStr = JSON.stringify(otherPhases, null, 2);
  } catch (e) {
    otherPhasesStr = '无法解析';
  }
}

return {
  language,
  outputLanguage,
  age: input.age || '7-9岁',
  duration: input.duration || '60分钟',
  scale: input.scale || '≤ 8人',
  title: input.title || '未命名课件',
  vocabulary: (input.vocabulary && input.vocabulary.length > 0) 
    ? (Array.isArray(input.vocabulary) ? input.vocabulary.join(', ') : input.vocabulary)
    : '请根据主题推荐词汇',
  grammar: (input.grammar && input.grammar.length > 0) 
    ? (Array.isArray(input.grammar) ? input.grammar.join(', ') : input.grammar)
    : '请根据主题推荐句型',
  theme: input.theme || '默认主题',
  requirements: input.requirements || '',
  phaseKey: phaseKey,
  phaseLabel: info.label,
  phaseDescription: info.description,
  timeRatio: info.timeRatio,
  phaseRecommendedMinutes: formatMinutes(phaseRecommendedMinutes),
  otherPhases: otherPhasesStr
};

const input = $input.first()?.json?.body || $input.first()?.json || {};
const clamp = (value, min, max) => Math.min(max, Math.max(min, Number(value) || min));
const phases = Array.isArray(input.lessonPlan) ? input.lessonPlan : [];
const compactPhases = phases
  .filter((phase) => phase && phase.key !== 'cover')
  .map((phase) => ({
    key: String(phase.key || ''),
    title: String(phase.title || ''),
    steps: (Array.isArray(phase.steps) ? phase.steps : []).map((step, index) => ({
      id: String(step.id || `${phase.key || 'phase'}-step-${index + 1}`),
      title: String(step.title || ''),
      duration: String(step.duration || step.time || ''),
      objective: String(step.objective || ''),
      activity: String(step.activity || ''),
      flow: String(step.flow || step.activitySteps || ''),
      resources: String(step.resources || '')
    }))
  }));
const stepCount = compactPhases.reduce((sum, phase) => sum + phase.steps.length, 0);
if (!stepCount) throw new Error('lessonPlan must contain at least one lesson step');
const totalSlides = clamp(input.totalSlides || stepCount * 2, Math.max(2, stepCount + 1), 40);
const styleMap = {
  'blue-business': 'Whimsical sky adventure with paper-cut clouds, rainbow colors, rounded shapes, bright blue, yellow, coral, mint and lavender.',
  'red-business': 'Magical storybook forest with hand-painted leaves, flowers, friendly woodland details, warm cream, green, teal, peach and yellow.',
  'nature-business': 'Playful space adventure with soft clay planets, friendly stars, orbit lines, indigo, violet, turquoise, coral and yellow.'
};
return [{ json: {
  courseTitle: String(input.courseMeta?.courseTitle || input.courseMeta?.title || input.courseTitle || 'English Learning Adventure'),
  courseContext: JSON.stringify(input.courseMeta || {}),
  lessonPlan: JSON.stringify(compactPhases),
  templateId: String(input.templateId || 'blue-business'),
  visualStyle: styleMap[input.templateId] || styleMap['blue-business'],
  totalSlides,
  stepCount,
  slideWidth: 940,
  slideHeight: 529
} }];

const raw = $input.first()?.json || {};
const prepared = $('Prepare Course Context').first().json;
const phases = JSON.parse(prepared.lessonPlan);
const stepMap = new Map(phases.flatMap((phase) => phase.steps.map((step) => [step.id, { ...step, phaseKey: phase.key, phaseTitle: phase.title }])));
const stepIds = [...stepMap.keys()];
const cjk = /[\u3400-\u4dbf\u4e00-\u9fff\uf900-\ufaff]/;

const stripCodeFence = (value) => String(value || '')
  .trim()
  .replace(/^\`{3}(?:json)?\s*/i, '')
  .replace(/\`{3}$/i, '')
  .trim();

const extractJsonObject = (value) => {
  const text = stripCodeFence(value);
  const first = text.indexOf('{');
  const last = text.lastIndexOf('}');
  return first >= 0 && last > first ? text.slice(first, last + 1) : text;
};

const parseJsonLike = (value) => {
  if (value && typeof value === 'object') return value;
  const extracted = extractJsonObject(value);
  try {
    return JSON.parse(extracted);
  } catch (error) {
    return { __parseError: error, __rawText: extracted };
  }
};

const extractCompleteSlideObjects = (text) => {
  const source = stripCodeFence(text);
  const slidesKey = source.search(/"slides"\s*:\s*\[/);
  if (slidesKey < 0) return [];
  const arrayStart = source.indexOf('[', slidesKey);
  const objects = [];
  let depth = 0;
  let start = -1;
  let inString = false;
  let escaped = false;
  for (let i = arrayStart + 1; i < source.length; i++) {
    const ch = source[i];
    if (inString) {
      if (escaped) {
        escaped = false;
      } else if (ch === '\\') {
        escaped = true;
      } else if (ch === '"') {
        inString = false;
      }
      continue;
    }
    if (ch === '"') {
      inString = true;
      continue;
    }
    if (ch === '{') {
      if (depth === 0) start = i;
      depth++;
      continue;
    }
    if (ch === '}') {
      depth--;
      if (depth === 0 && start >= 0) {
        const objectText = source.slice(start, i + 1);
        try { objects.push(JSON.parse(objectText)); } catch (error) {}
        start = -1;
      }
    }
  }
  return objects;
};

const cleanAscii = (value) => String(value || '')
  .replace(/[^\x09\x0A\x0D\x20-\x7E]/g, '')
  .replace(/[ \t]+/g, ' ')
  .trim();

const titleFromStep = (step, fallbackIndex) => {
  const base = cleanAscii(step?.title || step?.objective || step?.activity || 'Lesson Activity');
  return base.split(/[.!?。！？]/)[0].split(/\s+/).slice(0, 6).join(' ') || 'Lesson Activity ' + fallbackIndex;
};

const purposeFromStep = (step) => {
  const base = cleanAscii(step?.objective || step?.activity || step?.flow || 'Practice the target English through a clear activity.');
  return base.split(/[.!?。！？]/)[0].split(/\s+/).slice(0, 14).join(' ') || 'Practice the target English through a clear activity.';
};

const buildFallbackPlan = (existingSlides, candidateTitle) => {
  const output = [];
  const usedSteps = new Set();
  const addSlide = (slide) => {
    if (output.length >= prepared.totalSlides) return;
    const index = output.length;
    const isCover = index === 0;
    const rawStepId = isCover ? 'cover-step' : String(slide?.stepId || '');
    const step = stepMap.get(rawStepId);
    if (!isCover && !step) return;
    if (!isCover) usedSteps.add(rawStepId);
    output.push({
      id: 'slide-' + (index + 1),
      phaseKey: isCover ? 'cover' : step.phaseKey,
      stepId: isCover ? 'cover-step' : rawStepId,
      type: isCover ? 'cover' : cleanAscii(slide?.type || 'lesson'),
      title: cleanAscii(slide?.title || (isCover ? (candidateTitle || prepared.courseTitle) : titleFromStep(step, index + 1))),
      purpose: cleanAscii(slide?.purpose || (isCover ? 'Introduce the English learning adventure.' : purposeFromStep(step)))
    });
  };

  const sortedExisting = [...existingSlides]
    .filter((slide) => slide && typeof slide === 'object')
    .sort((a, b) => {
      const ai = Number(String(a.id || '').match(/slide-(\d+)/i)?.[1]) || 999;
      const bi = Number(String(b.id || '').match(/slide-(\d+)/i)?.[1]) || 999;
      return ai - bi;
    });
  sortedExisting.forEach(addSlide);
  if (!output.length) addSlide({ title: candidateTitle || prepared.courseTitle, purpose: 'Introduce the English learning adventure.' });
  const missingStepIds = stepIds.filter((stepId) => !usedSteps.has(stepId));
  for (const stepId of missingStepIds) {
    addSlide({ stepId });
  }
  const fillStepIds = missingStepIds.length ? missingStepIds : stepIds;
  let cursor = 0;
  while (output.length < prepared.totalSlides && fillStepIds.length) {
    const stepId = fillStepIds[cursor % fillStepIds.length];
    const step = stepMap.get(stepId);
    addSlide({ stepId, title: titleFromStep(step, output.length + 1), purpose: purposeFromStep(step) });
    cursor++;
  }
  return output;
};

let candidate = raw.output ?? raw.text ?? raw;
